//! Maps generated byte columns back to source bytes and proven mismatch sites.

use full_moon::ast::Expression;
use full_moon::node::Node;
use full_moon::tokenizer::{Symbol, TokenType};

use super::literal_precision_types::ExpectedSite;

#[derive(Clone, Debug, Default)]
pub(super) struct ColumnMap {
    additions: Vec<Vec<(usize, usize)>>,
    line_starts: Vec<usize>,
}

impl ColumnMap {
    pub(super) fn new(source: &str) -> Self {
        let mut line_starts = vec![0];
        line_starts.extend(
            source
                .match_indices('\n')
                .map(|(byte, _)| byte + 1)
                .filter(|&byte| byte < source.len()),
        );
        Self {
            additions: vec![Vec::new(); source.lines().count().max(1)],
            line_starts,
        }
    }

    pub(super) fn add(&mut self, source_byte: usize, width: usize) {
        let line = self
            .line_starts
            .partition_point(|&start| start <= source_byte)
            - 1;
        let column = source_byte - self.line_starts[line] + 1;
        self.additions[line].push((column, width));
    }

    pub(super) fn finish(&mut self) {
        for line in &mut self.additions {
            line.sort_unstable();
        }
    }

    pub(super) fn add_generated(&mut self, generated_source: &str, byte: usize, width: usize) {
        let line_start = generated_source[..byte]
            .rfind('\n')
            .map_or(0, |position| position + 1);
        let line = generated_source[..line_start]
            .bytes()
            .filter(|byte| *byte == b'\n')
            .count()
            + 1;
        let generated_column = byte - line_start + 1;
        let original_column = self.original(line, generated_column);
        let original_byte = self.source_byte(line, original_column);
        self.add(original_byte, width);
    }

    pub(super) fn original(&self, line: usize, generated: usize) -> usize {
        let Some(additions) = self.additions.get(line.saturating_sub(1)) else {
            return generated;
        };
        let mut inserted = 0;
        for &(original, width) in additions {
            let start = original + inserted;
            if generated <= start {
                break;
            }
            if generated <= start + width {
                return original;
            }
            inserted += width;
        }
        generated.saturating_sub(inserted).max(1)
    }

    pub(super) fn source_byte(&self, line: usize, column: usize) -> usize {
        self.line_starts
            .get(line.saturating_sub(1))
            .copied()
            .unwrap_or(0)
            + column.saturating_sub(1)
    }
}

#[derive(Clone, Debug)]
pub(super) struct TypeSite {
    bytes: std::ops::RangeInclusive<usize>,
    pub(super) member: String,
    pub(super) expected: String,
    pub(super) actual: &'static str,
    pub(super) hint: &'static str,
}

impl TypeSite {
    pub(super) fn overlaps(&self, start: usize, end: usize) -> bool {
        self.bytes.start() <= &end && self.bytes.end() >= &start
    }

    pub(super) fn mismatch(
        expression: &Expression,
        expected: &ExpectedSite,
        actual: Option<&'static str>,
    ) -> Option<Self> {
        let inferred = literal_actual(expression)?;
        if expected.accepts(expression) != Some(false) {
            return None;
        }
        let (start, end) = expression.range()?;
        Some(Self {
            bytes: start.bytes()..=end.bytes(),
            member: expected.member.clone(),
            expected: expected.expected.clone(),
            actual: actual.unwrap_or(inferred),
            hint: expected.hint,
        })
    }

    pub(super) fn invalid_option(
        expression: &Expression,
        model: &str,
        method: &str,
        options: &[crate::api::OptionSpec],
    ) -> Option<Self> {
        let (start, end) = expression.range()?;
        let names = options
            .iter()
            .map(|option| option.name)
            .collect::<Vec<_>>()
            .join(" | ");
        Some(Self {
            bytes: start.bytes()..=end.bytes(),
            member: format!("{model}.{method}.options"),
            expected: format!("known query option for {model}.{method} ({names})"),
            actual: "unsupported option",
            hint: "Use only the query options shown in expected.",
        })
    }
}

fn literal_actual(expression: &Expression) -> Option<&'static str> {
    match expression {
        Expression::String(_) => Some("string"),
        Expression::Number(_) => Some("number"),
        Expression::Symbol(token) => match token.token().token_type() {
            TokenType::Symbol {
                symbol: Symbol::True | Symbol::False,
            } => Some("boolean"),
            TokenType::Symbol {
                symbol: Symbol::Nil,
            } => Some("nil"),
            _ => None,
        },
        Expression::TableConstructor(_) => Some("table"),
        _ => None,
    }
}
